sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
    if (newValue === '1' || newValue === '2') {
        var gm = new GlideModal("glide_confirm_standard", true, 600);
        gm.setTitle("All priority 1 and priority 2 major incidents must be assessed and managed by the MIM team. Click 'okay' to confirm you are calling the MIM team on 01-123-123.");
        gm.setPreference("onPromptComplete", function() {});
        gm.setPreference("onPromptCancel", function() {
            return false;
        });
        gm.render();
    }
}
